#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdarg.h>
#include "tinymt32.h"

/**
* Prints a formatted output string.
*
* @param fmt   format string
* @param ...   variadic arguments
*/
void print( const char *fmt, ... ) {
	va_list args;
	va_start( args, fmt );
	vprintf( fmt, args );
	va_end( args );
}

/**
* Main execution sequence.
*/
int main( void ) {
	// Create a TinyMT32 state:
	tinymt32_t *state = malloc( sizeof(tinymt32_t) );
	if ( state == NULL ) {
		printf( "Error allocating memory.\n" );
		return 1;
	}

	// Initialize the state with a seed:
	uint32_t seed = 12345;
	tinymt32_init( state, seed );

	// Generate some random numbers:
	printf( "Random numbers from TinyMT32: seed = %u\n", seed );
	for ( int i = 0; i < 10; i++ ) {
		uint32_t r = tinymt32_generate_uint32( state );
		printf( "%u\n", r );
	}

	// Free allocated memory:
	free( state );

	return 0;
}
